33	/**
34	 * 联程行李装载交接核心业务：航段/行李登记、批量装载、封舱、到达确认与查询。
35	 * 所有写操作经 {@link IdempotencyService} 去重，业务变更与去重记录原子提交；
36	 * 航段行级锁（SELECT ... FOR UPDATE）保证装载与封舱并发时以版本决定唯一先后，
37	 * load_record 以 bag_tag 为主键保证同件行李不会进入两个清单。
38	 */
39	@Service
40	public class BaggageService {
41	
42	    private static final String LEG_OPEN = "OPEN";
43	    private static final String LEG_SEALED = "SEALED";
44	    private static final String LEG_ARRIVED = "ARRIVED";
45	    private static final String BAG_IN_TRANSIT = "IN_TRANSIT";
46	    private static final String BAG_SHORT_UNLOADED = "SHORT_UNLOADED";
47	    private static final String BAG_RECOVERED = "RECOVERED";
48	    private static final String BAG_DELIVERED = "DELIVERED";
49	    private static final String MODE_EXACT = "EXACT";
50	    private static final String MODE_DISCREPANCY = "DISCREPANCY";
51	
52	    private static final RowMapper<LegRow> LEG_MAPPER = (rs, rowNum) -> new LegRow(
53	            rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"),
54	            rs.getString("status"), rs.getInt("version"), rs.getString("sealed_manifest"),
55	            rs.getString("arrival_mode"), rs.getString("actual_arrivals"),
56	            rs.getString("short_manifest"), rs.getTimestamp("arrived_at"));
57	
58	    private static final RowMapper<BagRow> BAG_MAPPER = (rs, rowNum) -> new BagRow(
59	            rs.getString("bag_tag"), rs.getString("current_location"),
60	            rs.getInt("next_leg_index"), rs.getString("status"), rs.getString("loaded_leg_id"),
61	            rs.getString("short_leg_id"), rs.getString("short_destination"),
62	            rs.getTimestamp("short_registered_at"));
63	
64	    private static final RowMapper<ItineraryItem> ITINERARY_MAPPER = (rs, rowNum) -> new ItineraryItem(
65	            rs.getInt("seq"), rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"));
66	
67	    private final JdbcTemplate jdbcTemplate;
68	    private final IdempotencyService idempotencyService;
69	    private final ObjectMapper objectMapper;
70	    private final Clock clock;
71	
72	    public BaggageService(JdbcTemplate jdbcTemplate,
73	                          IdempotencyService idempotencyService,
74	                          ObjectMapper objectMapper,
75	                          Clock clock) {
76	        this.jdbcTemplate = jdbcTemplate;
77	        this.idempotencyService = idempotencyService;
78	        this.objectMapper = objectMapper;
79	        this.clock = clock;
80	    }
81	
82	    /** 登记航段：legId 唯一，初始状态 OPEN、版本 1。 */
83	    public LegResponse registerLeg(RegisterLegRequest request) {
84	        return idempotencyService.execute(request.requestId(), "REGISTER_LEG", 201,
85	                request, LegResponse.class, () -> doRegisterLeg(request));
86	    }
87	
88	    /** 登记行李：1~5 个无重复有序航段，相邻航段首尾站衔接，初始位于首段始发站。 */
89	    public BagResponse registerBag(RegisterBagRequest request) {
90	        return idempotencyService.execute(request.requestId(), "REGISTER_BAG", 201,
91	                request, BagResponse.class, () -> doRegisterBag(request));
92	    }
93	
94	    /** 批量装载：整批原子，任一行李不满足则 422 且无一件移动。 */
95	    public LoadResponse load(String legId, LoadRequest request) {
96	        LoadPayload payload = new LoadPayload(legId, request.expectedVersion(), sortedCopy(request.bagTags()));
97	        return idempotencyService.execute(request.requestId(), "LOAD", 200,
98	                payload, LoadResponse.class, () -> doLoad(legId, request));
99	    }
100	
101	    /** 封舱：校验版本，保存只读装载清单并转 SEALED；空清单也可封舱。 */
102	    public SealResponse seal(String legId, SealRequest request) {
103	        SealPayload payload = new SealPayload(legId, request.expectedVersion());
104	        return idempotencyService.execute(request.requestId(), "SEAL", 200,
105	                payload, SealResponse.class, () -> doSeal(legId, request));
106	    }
107	
108	    /** 到达确认：实际袋号集合须与封舱清单完全一致，匹配则原子转 ARRIVED 并推进各行李。 */
109	    public ArriveResponse arrive(String legId, ArriveRequest request) {
110	        ArrivePayload payload = new ArrivePayload(legId, sortedCopy(request.bagTags()));
111	        return idempotencyService.execute(request.requestId(), "ARRIVE", 200,
112	                payload, ArriveResponse.class, () -> doArrive(legId, request));
113	    }
114	
115	    /**
116	     * 差异到达：仅 SEALED 航段可提交；实际袋号不得重复且为封舱清单子集，
117	     * 实际到达者推进，缺失者转 SHORT_UNLOADED 并登记缺失航段/应到站/UTC 时刻。
118	     */
119	    public DiscrepancyArriveResponse arriveDiscrepancy(String legId, DiscrepancyArriveRequest request) {
120	        DiscrepancyPayload payload = new DiscrepancyPayload(
121	                legId, request.expectedVersion(), sortedCopy(request.actualBagTags()));
122	        return idempotencyService.execute(request.requestId(), "ARRIVE_DISCREPANCY", 200,
123	                payload, DiscrepancyArriveResponse.class, () -> doArriveDiscrepancy(legId, request));
124	    }
125	
126	    /**
127	     * 补到：仅 SHORT_UNLOADED 且缺失航段匹配的行李可补到；实际站须等于该航段到达站。
128	     * 成功后移动行李并推进待乘索引，标记 RECOVERED；完成行程者转 DELIVERED。
129	     */
130	    public RecoverResponse recover(String bagTag, RecoverRequest request) {
131	        RecoverPayload payload = new RecoverPayload(
132	                bagTag, request.missingLegId(), request.actualStation());
133	        return idempotencyService.execute(request.requestId(), "RECOVER", 200,
134	                payload, RecoverResponse.class, () -> doRecover(bagTag, request));
135	    }
136	
137	    /** 航段差异快照查询。 */
138	    public DiscrepancySnapshotResponse getDiscrepancySnapshot(String legId) {
139	        throw new UnsupportedOperationException("stub");
140	    }
141	
142	    /** 未补到清单查询（全局，按登记时刻、袋号排序）。 */
143	    public List<ShortUnloadedItem> listShortUnloaded() {
144	        throw new UnsupportedOperationException("stub");
145	    }
146	
147	    /** 行李轨迹查询。 */
148	    public BagResponse getBagTrace(String bagTag) {
149	        BagRow bag = findBag(bagTag);
150	        if (bag == null) {
151	            throw ApiException.notFound("行李不存在: " + bagTag);
152	        }
153	        return toBagResponse(bag);
154	    }
155	
156	    /** 封舱清单查询：未封舱时返回空清单。 */
157	    public ManifestResponse getManifest(String legId) {
158	        LegRow leg = findLeg(legId);
159	        if (leg == null) {
160	            throw ApiException.notFound("航段不存在: " + legId);
161	        }
162	        List<String> manifest = leg.sealedManifest() == null ? List.of() : readJsonList(leg.sealedManifest());
163	        return new ManifestResponse(leg.legId(), leg.status(), leg.version(), manifest);
164	    }
165	
166	    private LegResponse doRegisterLeg(RegisterLegRequest request) {
167	        if (findLeg(request.legId()) != null) {
168	            throw ApiException.conflict("航段已存在: " + request.legId());
169	        }
170	        jdbcTemplate.update(
171	                "INSERT INTO leg (leg_id, origin, destination, status, version) VALUES (?, ?, ?, ?, 1)",
172	                request.legId(), request.origin(), request.destination(), LEG_OPEN);
173	        return new LegResponse(request.legId(), request.origin(), request.destination(), LEG_OPEN, 1);
174	    }
175	
176	    private BagResponse doRegisterBag(RegisterBagRequest request) {
177	        List<String> legIds = request.legIds();
178	        if (new HashSet<>(legIds).size() != legIds.size()) {
179	            throw ApiException.unprocessable("行程航段不得重复");
180	        }
181	        if (findBag(request.bagTag()) != null) {
182	            throw ApiException.conflict("行李已存在: " + request.bagTag());
183	        }
184	        List<LegRow> legs = new ArrayList<>();
185	        for (String legId : legIds) {
186	            LegRow leg = findLeg(legId);
187	            if (leg == null) {
188	                throw ApiException.unprocessable("行程引用的航段不存在: " + legId);
189	            }
190	            legs.add(leg);
191	        }
192	        for (int i = 0; i + 1 < legs.size(); i++) {
193	            if (!legs.get(i).destination().equals(legs.get(i + 1).origin())) {
194	                throw ApiException.unprocessable(
195	                        "相邻航段首尾站必须衔接: " + legs.get(i).legId() + " -> " + legs.get(i + 1).legId());
196	            }
197	        }
198	        jdbcTemplate.update(
199	                "INSERT INTO bag (bag_tag, current_location, next_leg_index, status) VALUES (?, ?, 0, ?)",
200	                request.bagTag(), legs.get(0).origin(), BAG_IN_TRANSIT);
201	        for (int i = 0; i < legs.size(); i++) {
202	            LegRow leg = legs.get(i);
203	            jdbcTemplate.update(
204	                    "INSERT INTO bag_itinerary (bag_tag, seq, leg_id, origin, destination) VALUES (?, ?, ?, ?, ?)",
205	                    request.bagTag(), i, leg.legId(), leg.origin(), leg.destination());
206	        }
207	        return new BagResponse(request.bagTag(), legs.get(0).origin(), 0, BAG_IN_TRANSIT, null,
208	                toItinerary(request.bagTag()), List.of());
209	    }
210	
211	    private LoadResponse doLoad(String legId, LoadRequest request) {
212	        LegRow leg = lockLeg(legId);
213	        checkVersion(leg, request.expectedVersion());
214	        if (!LEG_OPEN.equals(leg.status())) {
215	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止装载");
216	        }
217	        List<String> bagTags = request.bagTags();
218	        if (new HashSet<>(bagTags).size() != bagTags.size()) {
219	            throw ApiException.unprocessable("批量装载的 bagTag 不得重复");
220	        }
221	        List<String> sorted = sortedCopy(bagTags);
222	        List<BagRow> bags = new ArrayList<>();
223	        for (String bagTag : sorted) {
224	            BagRow bag = lockBag(bagTag);
225	            if (bag == null) {
226	                throw ApiException.unprocessable("行李不存在: " + bagTag);
227	            }
228	            validateLoadable(bag, leg);
229	            bags.add(bag);
230	        }
231	        for (BagRow bag : bags) {
232	            jdbcTemplate.update("INSERT INTO load_record (bag_tag, leg_id) VALUES (?, ?)", bag.bagTag(), legId);
233	            jdbcTemplate.update("UPDATE bag SET loaded_leg_id = ? WHERE bag_tag = ?", legId, bag.bagTag());
234	        }
235	        int newVersion = leg.version() + 1;
236	        jdbcTemplate.update("UPDATE leg SET version = ? WHERE leg_id = ?", newVersion, legId);
237	        return new LoadResponse(legId, LEG_OPEN, newVersion, sorted);
238	    }
239	
240	    private SealResponse doSeal(String legId, SealRequest request) {
241	        LegRow leg = lockLeg(legId);
242	        checkVersion(leg, request.expectedVersion());
243	        if (!LEG_OPEN.equals(leg.status())) {
244	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止封舱");
245	        }
246	        List<String> manifest = jdbcTemplate.queryForList(
247	                "SELECT bag_tag FROM load_record WHERE leg_id = ? ORDER BY bag_tag", String.class, legId);
248	        int newVersion = leg.version() + 1;
249	        jdbcTemplate.update("UPDATE leg SET status = ?, version = ?, sealed_manifest = ? WHERE leg_id = ?",
250	                LEG_SEALED, newVersion, writeJson(manifest), legId);
251	        return new SealResponse(legId, LEG_SEALED, newVersion, manifest);
252	    }
253	
254	    private ArriveResponse doArrive(String legId, ArriveRequest request) {
255	        LegRow leg = lockLeg(legId);
256	        if (!LEG_SEALED.equals(leg.status())) {
257	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止到达确认");
258	        }
259	        List<String> manifest = readJsonList(leg.sealedManifest());
260	        List<String> actual = request.bagTags();
261	        Set<String> actualSet = new HashSet<>(actual);
262	        if (actualSet.size() != actual.size() || !actualSet.equals(new HashSet<>(manifest))) {
263	            throw ApiException.unprocessable("实际袋号集合与封舱清单不一致");
264	        }
265	        for (String bagTag : manifest) {
266	            BagRow bag = lockBag(bagTag);
267	            int nextIndex = bag.nextLegIndex() + 1;
268	            int total = itineraryCount(bagTag);
269	            String status = nextIndex >= total ? BAG_DELIVERED : BAG_IN_TRANSIT;
270	            jdbcTemplate.update(
271	                    "UPDATE bag SET current_location = ?, next_leg_index = ?, status = ?, loaded_leg_id = NULL"
272	                            + " WHERE bag_tag = ?",
273	                    leg.destination(), nextIndex, status, bagTag);
274	        }
275	        jdbcTemplate.update("DELETE FROM load_record WHERE leg_id = ?", legId);
276	        int newVersion = leg.version() + 1;
277	        jdbcTemplate.update("UPDATE leg SET status = ?, version = ? WHERE leg_id = ?",
278	                LEG_ARRIVED, newVersion, legId);
279	        return new ArriveResponse(legId, LEG_ARRIVED, newVersion, manifest);
280	    }
281	
282	    private DiscrepancyArriveResponse doArriveDiscrepancy(String legId, DiscrepancyArriveRequest request) {
283	        throw new UnsupportedOperationException("stub");
284	    }
285	
286	    private RecoverResponse doRecover(String bagTag, RecoverRequest request) {
287	        throw new UnsupportedOperationException("stub");
288	    }
289	
290	    private void validateLoadable(BagRow bag, LegRow leg) {
291	        if (bag.loadedLegId() != null) {
292	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已装载到航段 " + bag.loadedLegId());
293	        }
294	        ItineraryItem next = nextItinerary(bag.bagTag(), bag.nextLegIndex());
295	        if (next == null) {
296	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已完成全部行程");
297	        }
298	        if (!next.legId().equals(leg.legId())) {
299	            throw ApiException.unprocessable(
300	                    "行李 " + bag.bagTag() + " 当前待乘航段为 " + next.legId() + "，不能装载到 " + leg.legId());
301	        }
302	        if (!bag.currentLocation().equals(leg.origin())) {
303	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 不在航段始发站 " + leg.origin());
304	        }
305	    }
306	
307	    private void checkVersion(LegRow leg, int expectedVersion) {
308	        if (leg.version() != expectedVersion) {
309	            throw ApiException.conflict(
310	                    "航段版本冲突: 期望 " + expectedVersion + "，当前 " + leg.version());
311	        }
312	    }
313	
314	    private LegRow findLeg(String legId) {
315	        List<LegRow> rows = jdbcTemplate.query(
316	                "SELECT leg_id, origin, destination, status, version, sealed_manifest,"
317	                        + " arrival_mode, actual_arrivals, short_manifest, arrived_at"
318	                        + " FROM leg WHERE leg_id = ?",
319	                LEG_MAPPER, legId);
320	        return rows.isEmpty() ? null : rows.get(0);
321	    }
