324	        List<LegRow> rows = jdbcTemplate.query(
325	                "SELECT leg_id, origin, destination, status, version, sealed_manifest,"
326	                        + " arrival_mode, actual_arrivals, short_manifest, arrived_at"
327	                        + " FROM leg WHERE leg_id = ? FOR UPDATE",
328	                LEG_MAPPER, legId);
329	        if (rows.isEmpty()) {
330	            throw ApiException.notFound("航段不存在: " + legId);
331	        }
332	        return rows.get(0);
333	    }
