335	    private BagRow findBag(String bagTag) {
336	        List<BagRow> rows = jdbcTemplate.query(
337	                "SELECT bag_tag, current_location, next_leg_index, status, loaded_leg_id,"
338	                        + " short_leg_id, short_destination, short_registered_at"
339	                        + " FROM bag WHERE bag_tag = ?",
340	                BAG_MAPPER, bagTag);
341	        return rows.isEmpty() ? null : rows.get(0);
342	    }
