344	    private BagRow lockBag(String bagTag) {
345	        List<BagRow> rows = jdbcTemplate.query(
346	                "SELECT bag_tag, current_location, next_leg_index, status, loaded_leg_id,"
347	                        + " short_leg_id, short_destination, short_registered_at"
348	                        + " FROM bag WHERE bag_tag = ? FOR UPDATE",
349	                BAG_MAPPER, bagTag);
