353	    private ItineraryItem nextItinerary(String bagTag, int nextLegIndex) {
354	        List<ItineraryItem> rows = jdbcTemplate.query(
355	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? AND seq = ?",
356	                ITINERARY_MAPPER, bagTag, nextLegIndex);
357	        return rows.isEmpty() ? null : rows.get(0);
358	    }
