366	    private List<ItineraryItem> toItinerary(String bagTag) {
367	        return jdbcTemplate.query(
368	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? ORDER BY seq",
369	                ITINERARY_MAPPER, bagTag);
