    void snapshot_returnsNullModeBeforeArrivalAnd404ForUnknownLeg() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        mockMvc.perform(get("/api/legs/LEG1/discrepancy"))
                .andExpect(status().isOk())
